glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec4 a_texCoord;
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
out vec4 v_texCoord;
out float v_index;
#if USE_TEXTURE
  in vec2 a_uv0;
  out vec2 v_uv0;
#endif
void main() {
  vec4 pos = vec4(a_position, 1.0);
  v_index = pos.z;
  pos = cc_matViewProj * cc_matWorld * pos;
  #if CC_USE_MODEL
  #endif
  #if USE_TEXTURE
    v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  v_texCoord = a_texCoord;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
in vec4 v_color;
in vec2 v_uv0;
in vec4 v_texCoord;
in float v_index;
uniform sampler2D texture;
uniform sampler2D texture1;
uniform sampler2D texture2;
uniform sampler2D texture3;
uniform sampler2D texture4;
uniform sampler2D texture5;
uniform sampler2D texture6;
uniform sampler2D texture7;
const vec3 ORANGE_COLOR = vec3(0.99, 0.462, 0.062);
void main() {
  vec4 o = vec4(1, 1, 1, 1);
  #if USE_TEXTURE
    float uMin = v_texCoord.x;
    float uMax = v_texCoord.z;
    float vMin = v_texCoord.y;
    float vMax = v_texCoord.w;
    float vLength = vMax - vMin;
    float uLength = uMax - uMin;
    float u = v_uv0.x;
    float v = v_uv0.y;
    float relV = fract((v - vMin) / vLength);
    float finalV = vMin + relV * vLength;
    float relU = fract((u - uMin) / uLength);
    float finalU = uMin + relU * uLength;
    float index = v_index;
    vec2 finalUV = vec2(finalU, finalV);
    if (index < 1.0) {
      o = texture(texture, finalUV);
    } else if (index < 2.0) {
      o = texture(texture1, finalUV);
    } else if (index < 3.0) {
      o = texture(texture2, finalUV);
    } else if (index < 4.0) {
      o = texture(texture3, finalUV);
    } else if (index < 5.0) {
      o = texture(texture4, finalUV);
    } else if (index < 6.0) {
      o = texture(texture5, finalUV);
    } else if (index < 7.0) {
      o = texture(texture6, finalUV);
    } else {
      o = texture(texture7, finalUV);
    }
  #endif
  o *= v_color;
  #if USE_BGRA
    gl_FragColor = o.bgra;
  #else
    gl_FragColor = o.rgba;
  #endif
}

